#include <torch/extension.h>
#include <cuda_runtime.h>

// Define tile size for shared memory.
// It's a common practice to use a multiple of 32 for warp-level parallelism
// and to fit within typical shared memory limits per block.
#define TILE_SIZE 32

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Block-wise indices
    int blockRow = blockIdx.y;
    int blockCol = blockIdx.x;

    // Thread-wise indices within the block
    int threadRow = threadIdx.y;
    int threadCol = threadIdx.x;

    // Calculate the row and column of the C element this thread is responsible for
    int C_row = blockRow * TILE_SIZE + threadRow;
    int C_col = blockCol * TILE_SIZE + threadCol;

    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    float acc = 0.0f; // Accumulator for the dot product

    // Iterate over tiles
    // K is the dimension along which we perform the dot product (N in A, N in B)
    int numTiles = (N + TILE_SIZE - 1) / TILE_SIZE; // Number of tiles along K dimension

    for (int tile = 0; tile < numTiles; ++tile) {
        // Load tile of A into shared memory
        // As[threadRow][threadCol] corresponds to A[C_row][tile * TILE_SIZE + threadCol]
        int A_global_row = C_row;
        int A_global_col = tile * TILE_SIZE + threadCol;
        if (A_global_row < N && A_global_col < N) {
            As[threadRow][threadCol] = A[A_global_row * N + A_global_col];
        } else {
            As[threadRow][threadCol] = 0.0f; // Handle out-of-bounds with zero
        }

        // Load tile of B into shared memory
        // Bs[threadRow][threadCol] corresponds to B[tile * TILE_SIZE + threadRow][C_col]
        int B_global_row = tile * TILE_SIZE + threadRow;
        int B_global_col = C_col;
        if (B_global_row < N && B_global_col < N) {
            Bs[threadRow][threadCol] = B[B_global_row * N + B_global_col];
        } else {
            Bs[threadRow][threadCol] = 0.0f; // Handle out-of-bounds with zero
        }

        // Synchronize to ensure all shared memory loads are complete
        __syncthreads();

        // Perform dot product for the current tile
        for (int k = 0; k < TILE_SIZE; ++k) {
            acc += As[threadRow][k] * Bs[k][threadCol];
        }

        // Synchronize to ensure all threads in the block have finished with this tile's shared memory before the next load
        __syncthreads();
    }

    // Write result to global memory
    if (C_row < N && C_col < N) {
        C[C_row * N + C_col] = acc;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous and on CUDA device
    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0); // Assuming square matrices

    auto C = torch::zeros({N, N}, A.options()); // Output tensor

    // Grid dimensions
    // Each block processes a TILE_SIZE x TILE_SIZE submatrix
    int numBlocks = (N + TILE_SIZE - 1) / TILE_SIZE;
